<div class="grid"><section class="panel"><div class="panel-head"><div><h2>Cart items</h2><p><?=$sum['qty']?> item(s) from <?=count($sum['groups'])?> business(es)</p></div></div><?php if(!$sum['items']):?><div class="empty"><h3>Your cart is empty</h3><p>Add products from a business website to start an order.</p><a class="btn primary" href="/businesses.php">Browse Businesses</a></div><?php endif;?><?php foreach($sum['groups'] as $g):?><div class="seller"><div class="seller-head"><div><b><?=sk1230_h($g['business_name'])?></b><small class="pill"><?=count($g['items'])?> product(s)</small></div><strong><?=sk1230_money($g['subtotal'])?></strong></div><?php foreach($g['items'] as $it):?><div class="cart-item"><?php if($it['image_url']):?><img loading="lazy" src="<?=sk1230_h($it['image_url'])?>" alt=""><?php else:?><div></div><?php endif;?><div><h3><?=sk1230_h($it['product_name'])?></h3><small><?=sk1230_money($it['unit_price'])?> each</small><div><strong><?=sk1230_money((float)$it['unit_price']*(int)$it['qty'])?></strong></div></div><form method="post" class="qty"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="action" value="set"><input type="hidden" name="item_id" value="<?=(int)$it['id']?>"><input type="number" name="qty" min="0" max="99" value="<?=(int)$it['qty']?>"><button class="btn ghost">Update</button></form></div><?php endforeach;?></div><?php endforeach;?></section>
